import sys
from collections import Counter

def main():
    import sys
    input = sys.stdin.read().split()
    k = int(input[0])
    n = int(input[1])
    strings = input[2:]

    # Count occurrences of each character at each position
    char_count = [[Counter() for _ in range(n)] for _ in range(26)]
    for s in strings:
        for i, c in enumerate(s):
            char_count[ord(c) - ord('a')][i][c] += 1

    # Reconstruct the original string
    result = []
    used_positions = [False] * n

    for i in range(n):
        for j in range(26):
            if char_count[j][i]:
                c = chr(j + ord('a'))
                count = sum(char_count[j][i].values())
                if count == k:
                    result.append(c)
                    used_positions[i] = True
                    break

    # Check if we can form the string
    if len(result) != n:
        print(-1)
        return

    # Verify swaps
    for s in strings:
        diff_positions = [i for i in range(n) if s[i] != result[i]]
        if len(diff_positions) > 2:
            print(-1)
            return
        if len(diff_positions) == 2:
            i, j = diff_positions
            if s[i] != result[j] or s[j] != result[i]:
                print(-1)
                return

    print(''.join(result))

if __name__ == "__main__":
    main()
